import{_ as e,c as r,o as i,ah as n}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"49、【革】 離下兌上","description":"溫公易說 - 49、【革】 離下兌上","frontmatter":{"title":"49、【革】 離下兌上","description":"溫公易說 - 49、【革】 離下兌上"},"headers":[],"relativePath":"classics/wengong/050.md","filePath":"classics/wengong/050.md"}'),l={name:"classics/wengong/050.md"};function t(h,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[n('<h1 id="_49、【革】-離下兌上" tabindex="-1">49、【革】 離下兌上 <a class="header-anchor" href="#_49、【革】-離下兌上" aria-label="Permalink to “49、【革】 離下兌上”">​</a></h1><h3 id="彖曰-革-水火相息-二女同居-其志不相得-曰革。已日乃孚-革而信之。文明以說-大亨以正-革而當-其悔乃亡。" tabindex="-1">彖曰：革，水火相息，二女同居，其志不相得，曰革。已日乃孚，革而信之。文明以說，大亨以正，革而當，其悔乃亡。 <a class="header-anchor" href="#彖曰-革-水火相息-二女同居-其志不相得-曰革。已日乃孚-革而信之。文明以說-大亨以正-革而當-其悔乃亡。" aria-label="Permalink to “彖曰：革，水火相息，二女同居，其志不相得，曰革。已日乃孚，革而信之。文明以說，大亨以正，革而當，其悔乃亡。”">​</a></h3><p>天地革而四時成，湯武革命，順乎天而應乎人。革之時，大矣哉。革之為道，不可易也。故元亨利貞，而後悔亡也。初則民心未孚，故鞏用黃牛不可變也。二則得時之中，故已日革之，行有嘉也。</p><h3 id="象曰-澤中有火-革。君子以治歷明時。" tabindex="-1">象曰：澤中有火，革。君子以治歷明時。 <a class="header-anchor" href="#象曰-澤中有火-革。君子以治歷明時。" aria-label="Permalink to “象曰：澤中有火，革。君子以治歷明時。”">​</a></h3><h3 id="初九-鞏用黃牛之革-象曰-鞏用黃牛-不可以有為也。" tabindex="-1">初九：鞏用黃牛之革 象曰：鞏用黃牛，不可以有為也。 <a class="header-anchor" href="#初九-鞏用黃牛之革-象曰-鞏用黃牛-不可以有為也。" aria-label="Permalink to “初九：鞏用黃牛之革 象曰：鞏用黃牛，不可以有為也。”">​</a></h3><h3 id="六二-已日乃革之-徵吉-無咎-象曰-已日革之-行有嘉也。" tabindex="-1">六二：已日乃革之，徵吉，無咎 象曰：已日革之，行有嘉也。 <a class="header-anchor" href="#六二-已日乃革之-徵吉-無咎-象曰-已日革之-行有嘉也。" aria-label="Permalink to “六二：已日乃革之，徵吉，無咎 象曰：已日革之，行有嘉也。”">​</a></h3><h3 id="九三-徵兇-貞厲-革言三就-有孚-象曰-革言三就-又何之矣。" tabindex="-1">九三：徵兇，貞厲，革言三就，有孚 象曰：革言三就，又何之矣。 <a class="header-anchor" href="#九三-徵兇-貞厲-革言三就-有孚-象曰-革言三就-又何之矣。" aria-label="Permalink to “九三：徵兇，貞厲，革言三就，有孚 象曰：革言三就，又何之矣。”">​</a></h3><h3 id="九四-悔亡-有孚-改命-吉-象曰-改命之吉-信志也。" tabindex="-1">九四：悔亡，有孚，改命，吉 象曰：改命之吉，信志也。 <a class="header-anchor" href="#九四-悔亡-有孚-改命-吉-象曰-改命之吉-信志也。" aria-label="Permalink to “九四：悔亡，有孚，改命，吉 象曰：改命之吉，信志也。”">​</a></h3><h3 id="九五-大人虎變-未佔-有孚-象曰-大人虎變-其文炳也。" tabindex="-1">九五：大人虎變，未佔，有孚 象曰：大人虎變，其文炳也。 <a class="header-anchor" href="#九五-大人虎變-未佔-有孚-象曰-大人虎變-其文炳也。" aria-label="Permalink to “九五：大人虎變，未佔，有孚 象曰：大人虎變，其文炳也。”">​</a></h3><h3 id="上六-君子豹變-小人革面-徵兇-居貞吉-象曰-君子豹變-其文蔚也。小人革面-順以從君也。" tabindex="-1">上六：君子豹變，小人革面，徵兇，居貞吉 象曰：君子豹變，其文蔚也。小人革面，順以從君也。 <a class="header-anchor" href="#上六-君子豹變-小人革面-徵兇-居貞吉-象曰-君子豹變-其文蔚也。小人革面-順以從君也。" aria-label="Permalink to “上六：君子豹變，小人革面，徵兇，居貞吉 象曰：君子豹變，其文蔚也。小人革面，順以從君也。”">​</a></h3>',10)])])}const m=e(l,[["render",t]]);export{b as __pageData,m as default};
